def fill(x, end, forbid, r):
    """Tile [x,end) with bricks 2..6 wide (3-5 preferred), never repeating a span in `forbid`."""
    if x == end:
        return []
    for w in r.sample((2, 3, 3, 4, 4, 5, 5, 6), 8):
        if x + w > end or end - x - w == 1 or (x, x + w) in forbid:
            continue
        rest = fill(x + w, end, forbid, r)
        if rest is not None:
            return [(x, x + w)] + rest
    return None


def rowabove(prev, t, W, r):
    """A course laid over `prev` sharing exactly t spans with it."""
    if t > len(prev):
        return None
    keep = sorted(r.sample(range(len(prev)), t))
    forbid = set(prev)
    out = []
    x = 0
    for i in keep:
        a, b = prev[i]
        seg = fill(x, a, forbid, r)
        if seg is None:
            return None
        out += seg + [(a, b)]
        x = b
    seg = fill(x, W, forbid, r)
    return None if seg is None else out + seg


def feats(prev, row, W, old):
    """centred-on-a-wider, same-width-off-by-one, stray aligned joints, triple stacks."""
    ce = of = 0
    for u in row:
        for l in prev:
            if l[0] < u[0] and u[1] < l[1] and u[0] - l[0] == l[1] - u[1]:
                ce += 1
            if u[1] - u[0] == l[1] - l[0] and abs(u[0] - l[0]) == 1:
                of += 1
    tw = set(prev) & set(row)
    st = ({y for x, y in prev if y < W} & {y for x, y in row if y < W}
          ) - {c for sp in tw for c in sp}
    return ce, of, len(st), len(tw & old), tw


def spread(n, j, cap, r):
    """n twins over j junctions: at least one at the bottom, never all in one."""
    p = [0] * j
    p[0] = 1
    for _ in range(n - 1):
        c = [i for i in range(j) if p[i] < cap]
        if not c:
            return None
        p[r.choice(c)] += 1
    return None if max(p) == n and n > 1 else p


def tally(rows, W):
    """aligned joints, same-width-above pairs, near-twins, one-edge-only pairs."""
    al = sw = nt = ed = 0
    for a, b in zip(rows, rows[1:]):
        al += len({y for x, y in a if y < W} & {y for x, y in b if y < W})
        for u in b:
            for l in a:
                ed += (u[0] == l[0]) != (u[1] == l[1])
                if u[1] - u[0] == l[1] - l[0]:
                    sw += 1
                    nt += u != l
    return al, sw, nt, ed


def render(rows):
    return "\n".join("".join("[" + "-" * (b - a - 2) + "]" for a, b in row)
                      for row in reversed(rows))


def solve(clue):
    c, n = clue.split()
    N = int(n)
    r = random.Random(clue)
    base = []
    x = 0
    for t in re.findall(r"\[-*\]", c):
        base.append((x, x + len(t)))
        x += len(t)
    W = x
    hs = [h for h in (5, 6) if h != N and h != N + 1]
    lo = [h for h in (5, 6) if h != N] or [5, 6]
    for i in range(300):
        H = r.choice(hs if hs and i < 200 else lo)
        p = spread(N, H - 1, len(base), r)
        if p is None:
            continue
        rows = [base]
        ce = of = st = tri = 0
        old = set()
        for t in p:
            best = ()
            for _ in range(14):
                nr = rowabove(rows[-1], t, W, r)
                if not nr:
                    continue
                a, b, d, e, tw = feats(rows[-1], nr, W, old)
                v = (min(a, max(1 - ce, 0)) + min(b, max(1 - of, 0))
                     + min(d, max(2 - st, 0)) + min(e, max(1 - tri, 0)))
                if not best or v > best[0]:
                    best = (v, nr, a, b, d, e, tw)
            if not best:
                break
            rows.append(best[1])
            ce += best[2]
            of += best[3]
            st += best[4]
            tri += best[5]
            old = best[6]
        if len(rows) != H or ce < 1 or of < 1 or st < 2 or rows[0] == rows[-1]:
            continue
        if tri < (N > 2):
            continue
        if sum(b - a > 2 for u, v in zip(rows, rows[1:]) for a, b in set(u) & set(v)) < 1 + (N > 2):
            continue
        al, sw, nt, ed = tally(rows, W)
        if nt < 2 or ed < 2 or N in {H, H - 1, al, sw, nt, ed, ce, of, st,
                                     sum(len(u) for u in rows), len(rows[-1]),
                                     max(len(u) for u in rows),
                                     len({b - a for u in rows for a, b in u}),
                                     sum(1 for u in rows for a, b in u if b - a == 2)}:
            continue
        return render(rows)
    return ""
